const [paid, setPaid] = useState(false);

<ProgressButton
  variant="success"
  haptics
  fullWidth
  completed={paid}
  onComplete={() => setPaid(true)}
  onCompletedChange={setPaid}
>
  <ProgressButton.Label>{paid ? 'Paid' : 'Hold to pay'}</ProgressButton.Label>
</ProgressButton>

const [done, setDone] = useState(false);

<ProgressButton
  completed={done}
  onComplete={async () => {
    await submit();
    setDone(true);
  }}
  onCompletedChange={setDone}
>
  <ProgressButton.Label>Hold to submit</ProgressButton.Label>
</ProgressButton>
